#include <stdint.h>
#include <stdio.h>

#if !defined(__SOFT_FP__) && defined(__ARM_FP)
  #warning "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
#endif

uint32_t volatile *pRCCRegister;
uint32_t volatile *pGpioDModeRegister;
uint32_t volatile *pGpioDOutputRegister;
uint32_t volatile *pGpioDInputRegister;
uint32_t volatile *pGpioDPullRegister;

void Inintialize();
void CheckRow(uint32_t row);
void PrintResultAndWait(uint32_t column, uint32_t row);

int main(void)
{
	pRCCRegister = (uint32_t*)0x40023830;
	pGpioDModeRegister = (uint32_t*)0x40020C00;
	pGpioDOutputRegister = (uint32_t*)0x40020C14;
	pGpioDInputRegister = (uint32_t*)0x40020C10;
	pGpioDPullRegister = (uint32_t*)0x40020C0C;

	Inintialize();

	while(1)
	{
		*pGpioDOutputRegister &= ~(1 << 0);

		CheckRow(0);

		*pGpioDOutputRegister |= (1 << 0);
		*pGpioDOutputRegister &= ~(1 << 1);

		CheckRow(1);

		*pGpioDOutputRegister |= (1 << 1);
		*pGpioDOutputRegister &= ~(1 << 2);

		CheckRow(2);

		*pGpioDOutputRegister |= (1 << 2);
		*pGpioDOutputRegister &= ~(1 << 3);

		CheckRow(3);

		*pGpioDOutputRegister |= (1 << 3);
	}

    /* Loop forever */
	for(;;);
}

void Inintialize()
{
	//RCC enable for gpioD
	*pRCCRegister |= (1 << 3);

	//Set gpio mode for input for 8-11 pins
	*pGpioDModeRegister &= ~(0xFF << 16);

	//Enable pull-up for 8-11 pins

	//Clearing bits
	*pGpioDPullRegister &= ~(0xFF << 16);

	//Set bits
	*pGpioDPullRegister |= (0x55 << 16);

	//Set gpio mode for output for 0-3 pins

	//Clearing bits
	*pGpioDModeRegister &= ~(0xFF << 0);

	//Set bits
	*pGpioDModeRegister |= (0x55 << 0);

	//Set output register for pins 0-3 - HIGH

	*pGpioDOutputRegister |= (0xF << 0);
}

void CheckRow(uint32_t row)
{
	uint32_t inputData = 0;
	for(int i = 0; i < 4; i++)
	{
		inputData = *pGpioDInputRegister & (1 << (8 + i));;

		if(inputData == 0)
		{
			PrintResultAndWait(i, row);
		}
	}
}

